/**
 * Wave 10 / U-1b — Surge-500 generic consumer panel mount.
 *
 * Fail-soft `init({ viewer, mount, chip, trackLayer, t })`, following the
 * wave-3 dock-panel pattern. One panel renders ANY wired wave-10 spec:
 * a picker over WIRED_SPECS (wired.mjs — generated by
 * scripts/surge-consumer-audit.mjs from the spec catalogue; a spec that
 * is not spec-complete for the generic path, or not verifiably live, is
 * absent from the picker — enforcement by absence).
 *
 * The panel fetches the spec's own /api/<id> payload (served by the
 * generic spec engine) and renders it through model.js: provenance
 * (generic path + spec id), the payload's own source/attribution/
 * honesty, honestLabels, and the item rows — stale badged, never hidden.
 */
import { WIRED_SPECS } from './wired.mjs';
import { renderPanelHtml, refreshMsFor } from './model.js';

export function init({ viewer, mount, chip, trackLayer, t } = {}) {
  try {
    if (!viewer || typeof document === 'undefined') return null;
    const T = typeof t === 'function' ? t : (k) => k;

    let enabled = false;
    let destroyed = false;
    let refreshTimer = 0;
    let statusEl = null;
    let panelEl = null;
    let selectEl = null;
    let currentId =
      WIRED_SPECS.find((s) => s.id === 'nws-alerts-va')?.id ??
      WIRED_SPECS[0]?.id;

    function currentMeta() {
      return WIRED_SPECS.find((s) => s.id === currentId) ?? WIRED_SPECS[0];
    }

    async function load() {
      if (destroyed || !enabled) return;
      const meta = currentMeta();
      if (!meta) return;
      try {
        const res = await fetch(`/api/${meta.id}`);
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const json = await res.json();
        if (destroyed || !enabled) return;
        if (panelEl) panelEl.innerHTML = renderPanelHtml(meta, json);
        if (statusEl)
          statusEl.textContent =
            `${meta.title} · ${json.count ?? 0} items` +
            (json.stale ? ' · stale' : '');
      } catch {
        if (statusEl)
          statusEl.textContent = `${meta.title} unavailable — retrying`;
      }
    }

    function armTimer() {
      clearInterval(refreshTimer);
      if (!enabled || destroyed) return;
      refreshTimer = setInterval(load, refreshMsFor(currentMeta()));
    }

    function setEnabled(on) {
      enabled = on;
      if (on) {
        void load();
        armTimer();
      } else {
        clearInterval(refreshTimer);
      }
    }

    if (mount && typeof chip === 'function' && WIRED_SPECS.length > 0) {
      try {
        statusEl = document.createElement('div');
        statusEl.style.cssText =
          'font-size:10px;color:#8aa4d6;margin:2px 0 4px;';
        statusEl.textContent = 'surge feed off — enable to load.';
        mount.appendChild(statusEl);

        selectEl = document.createElement('select');
        selectEl.style.cssText =
          'width:100%;font-size:10px;margin:2px 0;padding:3px;border-radius:6px;' +
          'border:1px solid #2a3b66;background:#0a1220;color:#c8d6f5;';
        selectEl.setAttribute('aria-label', 'Surge-500 wired feed');
        // Lazy options: WIRED_SPECS runs to ~479 entries, and building all
        // of them as <option> nodes up front is hundreds of DOM nodes for a
        // control most sessions never open. Ship just the current feed's
        // option and populate the full list on first interaction
        // (pointerdown/focus fire before the native popup renders).
        let optionsPopulated = false;
        const populateOptions = () => {
          if (optionsPopulated) return;
          optionsPopulated = true;
          selectEl.innerHTML = '';
          for (const s of WIRED_SPECS) {
            const opt = document.createElement('option');
            opt.value = s.id;
            opt.textContent = s.title;
            if (s.id === currentId) opt.selected = true;
            selectEl.appendChild(opt);
          }
        };
        const currentSpec = WIRED_SPECS.find((s) => s.id === currentId);
        const initialOpt = document.createElement('option');
        initialOpt.value = currentId;
        initialOpt.textContent = currentSpec
          ? currentSpec.title
          : 'Select a feed…';
        initialOpt.selected = true;
        selectEl.appendChild(initialOpt);
        selectEl.addEventListener('pointerdown', populateOptions);
        selectEl.addEventListener('focus', populateOptions);
        selectEl.addEventListener('change', () => {
          currentId = selectEl.value;
          if (statusEl) statusEl.textContent = 'loading…';
          if (panelEl) panelEl.innerHTML = '';
          void load();
          armTimer();
        });
        mount.appendChild(selectEl);

        panelEl = document.createElement('div');
        panelEl.style.cssText = 'max-height:480px;overflow:auto;';
        mount.appendChild(panelEl);

        const apply = (on) => setEnabled(on);
        if (typeof trackLayer === 'function') {
          const tracked = trackLayer('surgeGeneric', {
            enable: () => setEnabled(true),
            disable: () => setEnabled(false),
          });
          mount.appendChild(
            chip(
              T('feature.surgeGeneric') || 'Surge-500 feeds',
              (on) => (on ? tracked.show() : tracked.hide()),
              false,
            ),
          );
        } else {
          mount.appendChild(
            chip(T('feature.surgeGeneric') || 'Surge-500 feeds', apply, false),
          );
        }

        const legend = document.createElement('div');
        legend.style.cssText =
          'font-size:10px;color:#8aa4d6;margin-top:4px;line-height:1.5;';
        legend.textContent =
          `${WIRED_SPECS.length} of the 502 Surge-500 specs are wired into ` +
          'this generic panel: each passed the generic-path audit and a live ' +
          'check. Specs that failed either test are absent — not degraded.';
        mount.appendChild(legend);
      } catch {
        /* dock UI optional */
      }
    }

    return function destroy() {
      destroyed = true;
      setEnabled(false);
    };
  } catch (error) {
    console.warn('[wave10 surgeGeneric] init failed:', error);
    return null;
  }
}
